/**
 * Early-instrumentation entrypoint: `import "@sazabi/react-native/register"`.
 *
 * Importing this module installs the SDK's `XMLHttpRequest` patch as a
 * dormant, transparent passthrough at module-evaluation time, before any
 * other library's module-scope code can capture the prototype methods
 * (Metro evaluates an entry file's imports in order, and every static import
 * runs before the first statement). `init()` later activates it with
 * configuration; until then it observes nothing, stores nothing, and sends
 * nothing.
 *
 * Put this import above all other imports in your app's entry module.
 */
import { isWebHost } from "./host";
import { ensureNetworkPatches } from "./network";

try {
  // react-native-web runs in a browser, where @sazabi/browser owns capture.
  if (!isWebHost()) {
    ensureNetworkPatches();
  }
} catch {
  // Registration must never break the host app; init() re-ensures.
}
